    val status: DecisionStatus? = null,
    val assigneeId: Patchable<String> = Patchable.Unset,
    val description: String? = null,
    val optionsConsidered: String? = null,
    val objective: String? = null,
    val testDescription: String? = null,
    val results: String? = null,
    val outcome: String? = null,
    val reasoning: String? = null,
    val concludedOn: String? = null,
) : ApiRequest {
    companion object {
        const val titleMaxLength = 300
        const val titleMinLength = 1
        const val descriptionMaxLength = 20000
        const val optionsConsideredMaxLength = 20000
        const val objectiveMaxLength = 20000
        const val testDescriptionMaxLength = 20000
        const val resultsMaxLength = 20000
        const val outcomeMaxLength = 20000
        const val reasoningMaxLength = 20000
    }

    override fun toJson(): JsonElement = buildJsonObject {
        type?.let { put("type", JsonPrimitive(it.rawValue)) }
        title?.let { put("title", JsonPrimitive(it)) }
        status?.let { put("status", JsonPrimitive(it.rawValue)) }
        assigneeId.encodeInto(this, "assigneeId") { JsonPrimitive(it) }
        description?.let { put("description", JsonPrimitive(it)) }
        optionsConsidered?.let { put("optionsConsidered", JsonPrimitive(it)) }
        objective?.let { put("objective", JsonPrimitive(it)) }
        testDescription?.let { put("testDescription", JsonPrimitive(it)) }
        results?.let { put("results", JsonPrimitive(it)) }
        outcome?.let { put("outcome", JsonPrimitive(it)) }
        reasoning?.let { put("reasoning", JsonPrimitive(it)) }
        concludedOn?.let { put("concludedOn", JsonPrimitive(it)) }
